patch:
diff --git a/repro/no-unused-expressions-use-strict.js b/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..7735e72
--- /dev/null
+++ b/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,17 @@
+"use strict";
+// Repro: no-unused-expressions reports "use strict" when parsed with ecmaVersion 3 (9.25.0 regression).
+const { Linter } = require("../lib/api");
+const linter = new Linter();
+const code = `"use strict";\nfunction f() { "use strict"; return 1; }\nf();\n`;
+const rules = { "no-unused-expressions": ["error", { allowShortCircuit: true, allowTernary: true, allowTaggedTemplates: true }] };
+let failed = false;
+for (const ecmaVersion of [3, 5, "latest"]) {
+	for (const sourceType of ["script", "commonjs"]) {
+		const msgs = linter.verify(code, { languageOptions: { ecmaVersion, sourceType }, rules });
+		console.log(`ecmaVersion=${ecmaVersion} sourceType=${sourceType}: ${msgs.length} problem(s)`, msgs.map(m => `${m.line}:${m.column} ${m.ruleId} ${m.message}`));
+		if (msgs.length) failed = true;
+	}
+}
+const ast = require("espree").parse(code, { ecmaVersion: 3 });
+console.log("espree ecmaVersion 3, first statement .directive =", ast.body[0].directive);
+process.exitCode = failed ? 1 : 0;
